GET /api/v1/teams/{team_id}/settings
// Internal admin console. team_id is shown in the UI nav to every employee,
// so team existence is not confidential. Only team owners may read settings.

// Caller is an employee, not an owner of team-42:
→ 403 Forbidden
   {"error": {"code": "forbidden", "message": "Owner role required", "trace_id": "req-7"}}

// Spec: "Every endpoint under /teams/{team_id} answers 403 on role failure.
//        Ownership is verified server-side before any read."
// Server logs the denial with identical detail whether the team exists or not.
